/// Where the sidecar is listening and the token minted for this session.
///
/// Both values come from the sidecar's startup handshake. Process supervision
/// that produces them lands with the Windows distribution work; until then this
/// is constructed by tests.
class SidecarConnection {
  const SidecarConnection({required this.baseUrl, required this.token});

  /// Origin of the sidecar, e.g. `http://127.0.0.1:52348`.
  final String baseUrl;

  /// Per-session bearer token. Never logged.
  final String token;
}

/// What went wrong with a sidecar call, once transport details are stripped.
enum SidecarErrorKind {
  /// The sidecar could not be reached (not started, wrong port, refused).
  unavailable,

  /// The request outlived its timeout.
  timeout,

  /// The caller cancelled the request via a [CancelToken].
  cancelled,

  /// The sidecar rejected the bearer token (HTTP 401).
  unauthorized,

  /// The sidecar refused the request as conflicting with the current state
  /// (HTTP 409): a stale `expected_version` (someone else already acted on
  /// this question), no AI grade to approve/edit yet, nothing left to undo
  /// (Issue #22 acceptance: "同時/重複requestが…古いversionの更新を拒否する"),
  /// or one of `POST .../export`'s refusals.
  ///
  /// **One kind, many causes with different remedies.** Read
  /// [SidecarApiException.conflictCode] before telling the user what to do
  /// about it; assuming a single cause is exactly what Issue #150 fixed.
  conflict,

  /// The sidecar answered with an error status or an unreadable body.
  badResponse,

  /// Anything else.
  unknown,
}

/// The only exception callers of [SidecarApiClient] need to handle.
class SidecarApiException implements Exception {
  SidecarApiException(
    this.kind,
    this.message, {
    this.statusCode,
    this.conflictCode,
    this.conflictQuestionIds,
  });

  final SidecarErrorKind kind;
  final String message;
  final int? statusCode;

  /// The sidecar's own name for *which* refusal a 409 is
  /// (`domain.pdf_export.ExportRefusalReason`), or `null` when the body
  /// carries none.
  ///
  /// [SidecarErrorKind.conflict] covers every 409 the sidecar can answer,
  /// and `POST .../export` alone has two with **opposite remedies**: one the
  /// reviewer fixes by confirming the questions, one confirming cannot fix
  /// at all. Reading this instead of assuming is what Issue #150 found
  /// missing -- the caller had been printing Issue #23's wording over both,
  /// so a reviewer who had confirmed everything was told to confirm it
  /// again. Callers must treat an unrecognised (or `null`) code as "some
  /// refusal I don't know the shape of" and fall back to [message], never
  /// to a guess.
  final String? conflictCode;

  /// The question ids a 409 names as its subject (`detail.question_ids`) --
  /// what [conflictCode] says about them differs per code. `null` for every
  /// error that carries no such list.
  final List<String>? conflictQuestionIds;

  @override
  String toString() =>
      'SidecarApiException($kind, "$message", status: $statusCode, '
      'code: $conflictCode)';
}

/// Raised by [SidecarApiClient.createSubmission] when the sidecar already has
/// a submission with the same PDF content for this test (409) -- Issue #17's
/// reintake policy (docs/answer-intake-and-preprocessing.md §2). Carries the
/// existing submission id so the UI can point the user at it instead of just
/// showing a generic error.
class DuplicateSubmissionException implements Exception {
  DuplicateSubmissionException(this.message, this.existingSubmissionId);

  final String message;
  final String existingSubmissionId;

  @override
  String toString() =>
      'DuplicateSubmissionException("$message", existing: $existingSubmissionId)';
}

/// Thin, typed boundary over the generated sidecar client.
class SidecarApiClient {
  SidecarApiClient(
    SidecarConnection connection, {
    Duration timeout = const Duration(seconds: 10),
    Duration intakeTimeout = const Duration(minutes: 5),
    Dio? dio,
    Dio? uploadDio,
  }) : _dio = dio ?? Dio(),
       _uploadDio = uploadDio ?? Dio() {
    _configure(_dio, connection, timeout);
    _configure(_uploadDio, connection, intakeTimeout);
    // Pass an empty interceptor list so the generated client does not also
    // register its own auth interceptors on top of ours.
    final generated = AutoScoringApi(dio: _dio, interceptors: const []);
    _api = generated.getDefaultApi();
    _testRegistrationApi = generated.getTestRegistrationApi();
    _dependencyGraphApi = generated.getDependencyGraphApi();
    final uploadGenerated = AutoScoringApi(
      dio: _uploadDio,
      interceptors: const [],
    );
    _uploadApi = uploadGenerated.getDefaultApi();
    // Registering a test uploads several files in one request, same rationale
    // as createSubmission below -- it needs the longer intake timeout, not the
    // near-instant default.
    _uploadTestRegistrationApi = uploadGenerated.getTestRegistrationApi();
    _intakeApi = generated.getIntakeApi();
    // Classification uploads one PDF and waits on a provider round trip, so it
    // shares the upload client's headroom rather than the near-instant default.
    _uploadIntakeApi = uploadGenerated.getIntakeApi();
    _criteriaApi = generated.getCriteriaApi();
    // Extraction renders every page of the 採点基準PDF and then waits on one
    // multimodal call over all of them -- minutes, not the near-instant
    // default. Same reason `createTest` uses the upload client.
    _uploadCriteriaApi = uploadGenerated.getCriteriaApi();
    _recognitionsApi = generated.getRecognitionsApi();
    _reviewApi = generated.getReviewApi();
    _jobsApi = generated.getJobsApi();
    _exportApi = generated.getExportApi();
  }

  static void _configure(
    Dio dio,
    SidecarConnection connection,
    Duration timeout,
  ) {
    final baseUrl = _validatedLoopbackBaseUrl(connection.baseUrl);
    dio.options
      ..baseUrl = baseUrl
      ..connectTimeout = timeout
      ..sendTimeout = timeout
      ..receiveTimeout = timeout;
    dio.interceptors.add(
      InterceptorsWrapper(
        onRequest: (options, handler) {
          if (options.path != '/healthz') {
            options.headers['Authorization'] = 'Bearer ${connection.token}';
          }
          handler.next(options);
        },
      ),
    );
  }

  final Dio _dio;
  late final DefaultApi _api;
  late final TestRegistrationApi _testRegistrationApi;
  late final CriteriaApi _criteriaApi;
  late final CriteriaApi _uploadCriteriaApi;
  late final DependencyGraphApi _dependencyGraphApi;
  late final RecognitionsApi _recognitionsApi;
  late final ReviewApi _reviewApi;
  late final JobsApi _jobsApi;
  late final ExportApi _exportApi;
  late final IntakeApi _intakeApi;

  /// A second Dio/client pair, configured with [intakeTimeout] instead of
  /// [timeout], for [createSubmission]. Rasterizing, deskewing and cropping
  /// every page of a large answer PDF happens inside that one request before
  /// the sidecar responds, so it needs far more headroom than the other
  /// (near-instant) calls share -- otherwise the client reports a timeout
  /// failure while the sidecar keeps working and commits anyway, and a
  /// client-side retry on the same bytes would then just surface as a
  /// confusing duplicate-submission conflict.
  final Dio _uploadDio;
  late final DefaultApi _uploadApi;
  late final TestRegistrationApi _uploadTestRegistrationApi;
  late final IntakeApi _uploadIntakeApi;

  /// Plan a scanned batch against a saved 取込の型 (Issue #101).
  ///
  /// **Sends no file bytes** -- only names, sizes and content digests. The
  /// rules assign what they can and the response says how many files would
  /// still cost an LLM call, which is what the pre-flight "how many calls"
  /// number is built from. Asking costs nothing.
  Future<IntakePlanResponse> planIntake({
    required String templateId,
    required String rootName,
    required List<ScannedFileModel> files,
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _intakeApi.planIntakeIntakePlanPost(
        planRequest: PlanRequest(
          (builder) => builder
            ..templateId = templateId
            ..rootName = rootName
            ..files.replace(files),
        ),
        cancelToken: cancelToken,
      );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Every saved 取込の型 (設定画面).
  Future<List<IntakeTemplateModel>> listIntakeTemplates({
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _intakeApi.listTemplatesIntakeTemplatesGet(
        cancelToken: cancelToken,
      );
      return _requireBody(response).toList();
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Replace the saved 取込の型 with [templates].
  ///
  /// Whole-list replace, not per-template upsert: the settings screen edits a
  /// list (rows are reordered and removed), and a merge would have to guess
  /// whether an absent template was deleted or simply not sent.
  Future<List<IntakeTemplateModel>> saveIntakeTemplates(
    List<IntakeTemplateModel> templates, {
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _intakeApi.saveTemplatesIntakeTemplatesPut(
        saveTemplatesRequest: SaveTemplatesRequest(
          (builder) => builder..templates.replace(templates),
        ),
        cancelToken: cancelToken,
      );
      return _requireBody(response).toList();
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// The per-call price the reviewer entered, or `null` for "not set".
  ///
  /// `null` is not zero. This app cannot know what a provider charges -- it
  /// depends on the provider, the model and the day -- so the screen says the
  /// price is unknown rather than printing an invented figure.
  Future<double?> intakeCost({CancelToken? cancelToken}) async {
    try {
      final response = await _intakeApi.getIntakeCostIntakeCostGet(
        cancelToken: cancelToken,
      );
      return _requireBody(response).classificationUnitCost?.toDouble();
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Record the per-call price. `null` clears it back to "not set".
  Future<double?> saveIntakeCost(
    double? unitCost, {
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _intakeApi.saveIntakeCostIntakeCostPut(
        intakeCostModel: IntakeCostModel(
          (builder) => builder..classificationUnitCost = unitCost,
        ),
        cancelToken: cancelToken,
      );
      return _requireBody(response).classificationUnitCost?.toDouble();
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Whether this host can classify at all, and if not, why.
  ///
  /// Never throws: like grading availability, "no provider configured" is a
  /// state the screen renders -- rules still work and the reviewer can assign
  /// every role by hand.
  Future<ClassificationAvailabilityResponse> classificationAvailability({
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _intakeApi
          .classificationAvailabilityIntakeClassificationAvailabilityGet(
            cancelToken: cancelToken,
          );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Ask what one file is, from its first page.
  ///
  /// One file per call on purpose: progress, partial results and cancellation
  /// then need nothing but ordinary HTTP. Callers send only files the rules
  /// did not match.
  Future<RoleProposalResponse> classifyMaterial({
    required String path,
    CancelToken? cancelToken,
  }) async {
    final MultipartFile file;
    try {
      file = await MultipartFile.fromFile(path);
    } catch (error) {
      throw SidecarApiException(
        SidecarErrorKind.unknown,
        'could not read the selected file: $error',
      );
    }
    try {
      final response = await _uploadIntakeApi
          .classifyMaterialIntakeClassifyPost(
            file: file,
            cancelToken: cancelToken,
          );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Ask which of [candidates] one answer belongs to.
  ///
  /// **Never call this with fewer than two candidates.** With one the answer
  /// is already decided and the sidecar refuses -- spending a provider call to
  /// confirm a foregone conclusion is exactly what the reviewer's own
  /// narrowing step exists to avoid.
  Future<AttributionProposalResponse> attributeAnswer({
    required String path,
    required List<({String id, String label})> candidates,
    CancelToken? cancelToken,
  }) async {
    final MultipartFile file;
    try {
      file = await MultipartFile.fromFile(path);
    } catch (error) {
      throw SidecarApiException(
        SidecarErrorKind.unknown,
        'could not read the selected file: $error',
      );
    }
    try {
      final response = await _uploadIntakeApi
          .attributeAnswerIntakeAttributePost(
            file: file,
            candidateIds: BuiltList<String>([
              for (final candidate in candidates) candidate.id,
            ]),
            candidateLabels: BuiltList<String>([
              for (final candidate in candidates) candidate.label,
            ]),
            cancelToken: cancelToken,
          );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Liveness probe. Never throws: an unreachable sidecar is a state the UI
  /// renders, not an error. The endpoint itself needs no auth.
  Future<bool> isHealthy({CancelToken? cancelToken}) async {
    try {
      final response = await _api.healthzHealthzGet(cancelToken: cancelToken);
      return response.data?['status'] == 'ok';
    } on DioException {
      return false;
    }
  }

  /// Whether this installation can AI-grade at all, and if not, why
  /// (Issue #97).
  ///
  /// Answers a question no other call can: every grading job on a host with
  /// no credentials fails the same way an unreadable answer does, so without
  /// this the reviewer cannot tell "this machine cannot grade" from "the AI
  /// could not read this one". `reason` names configuration variables and
  /// host prerequisites only -- the sidecar keeps credential *values* out of
  /// it by construction (`api/app.py` の `build_ai_provider`).
  ///
  /// Throws [SidecarApiException] on any failure, like every other call here:
  /// "the sidecar did not answer" is not the same fact as "grading is
  /// unavailable", and a caller that conflated them would announce a
  /// configuration problem every time a request timed out.
  Future<GradingAvailabilityResponse> gradingAvailability({
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _api.gradingAvailabilityGradingAvailabilityGet(
        cancelToken: cancelToken,
      );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Score one answer. Throws [SidecarApiException] on any failure.
  Future<ScoreResponse> score({
    required String key,
    required int raw,
    required int maximum,
    CancelToken? cancelToken,
  }) async {
    try {
      final request = ScoreRequest(
        (builder) => builder
          ..key = key
          ..raw = raw
          ..maximum = maximum,
      );
      final response = await _api.scoreScorePost(
        scoreRequest: request,
        cancelToken: cancelToken,
      );
      final body = response.data;
      if (body == null) {
        throw SidecarApiException(
          SidecarErrorKind.badResponse,
          'sidecar returned an empty body',
          statusCode: response.statusCode,
        );
      }
      return body;
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

