  /// Requeues a `FAILED` job (Issue #23: 出力の再試行).
  Future<JobResponse> retryJob(String jobId, {CancelToken? cancelToken}) async {
    try {
      final response = await _jobsApi.retryJobJobsJobIdRetryPost(
        jobId: jobId,
        cancelToken: cancelToken,
      );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Exports every answer sheet of [testId] in one request (Issue #142),
  /// optionally narrowed to [submissionIds].
  ///
  /// **The result is a row per submission, not a single verdict.** One
  /// unconfirmed or unrenderable sheet in a run of 40 must not cost the
  /// reviewer the other 39, so the refusals the single-sheet
  /// [requestExport] raises as a 409 come back here as
  /// `BulkExportItemStatus.refused` rows carrying their reason
  /// (`domain.pdf_export.ExportRefusalReason`). Re-running only what failed
  /// is the same call with a shorter [submissionIds].
  Future<BulkExportResponse> requestBulkExport(
    String testId, {
    List<String>? submissionIds,
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _exportApi.requestBulkExportTestsTestIdExportPost(
        testId: testId,
        bulkExportRequest: submissionIds == null
            ? null
            : BulkExportRequest((b) => b..submissionIds.replace(submissionIds)),
        cancelToken: cancelToken,
      );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// The generated PDF's bytes, by `Export.id` (Issue #142).
  ///
  /// The app writes each sheet into the folder the reviewer picked, and it
  /// **deliberately does not know where the sidecar's `app-data/` is**
  /// (`main.dart`), so `Export.file_path` -- relative to that root -- is not
  /// something it can open. Bytes are; same shape as [getSourcePdf].
  Future<Uint8List> getExportFile(
    String exportId, {
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _exportApi.getExportFileExportsExportIdFileGet(
        exportId: exportId,
        cancelToken: cancelToken,
      );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Cancels a `QUEUED`/`RUNNING` job (Issue #142: 中止).
  ///
  /// A bulk run queues every sheet up front, so stopping it means telling
  /// the sidecar to drop the ones it has not started -- otherwise "中止"
  /// would only stop the app from *watching*, and the machine would keep
  /// rendering PDFs nobody asked for any more.
  Future<JobResponse> cancelJob(
    String jobId, {
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _jobsApi.cancelJobJobsJobIdCancelPost(
        jobId: jobId,
        cancelToken: cancelToken,
      );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  T _requireBody<T>(Response<T> response) {
    final body = response.data;
    if (body == null) {
      throw SidecarApiException(
        SidecarErrorKind.badResponse,
        'sidecar returned an empty body',
        statusCode: response.statusCode,
      );
    }
    return body;
  }

  DuplicateSubmissionException? _duplicateSubmission(DioException error) {
    if (error.response?.statusCode != 409) return null;
    final detail = error.response?.data is Map
        ? (error.response!.data as Map)['detail']
        : null;
    if (detail is! Map) return null;
    final existingId = detail['existing_submission_id'];
    if (existingId is! String) return null;
    final message = detail['message'];
    return DuplicateSubmissionException(
      message is String ? message : 'duplicate submission',
      existingId,
    );
  }

  /// Release the underlying HTTP connections.
  void close() {
    _dio.close(force: true);
    _uploadDio.close(force: true);
  }

  SidecarApiException _translate(DioException error) {
    switch (error.type) {
      case DioExceptionType.connectionTimeout:
      case DioExceptionType.connectionError:
        // No TCP connection to a loopback port within the budget means the
        // sidecar is not there, not that it is slow.
        return SidecarApiException(
          SidecarErrorKind.unavailable,
          'sidecar is not reachable',
        );
      case DioExceptionType.sendTimeout:
      case DioExceptionType.receiveTimeout:
      case DioExceptionType.transformTimeout:
        return SidecarApiException(
          SidecarErrorKind.timeout,
          'sidecar request timed out',
        );
      case DioExceptionType.cancel:
        return SidecarApiException(
          SidecarErrorKind.cancelled,
          'sidecar request was cancelled',
        );
      case DioExceptionType.badResponse:
        final status = error.response?.statusCode;
        if (status == 401) {
          return SidecarApiException(
            SidecarErrorKind.unauthorized,
            'sidecar rejected the bearer token',
            statusCode: status,
          );
        }
        if (status == 409) {
          return SidecarApiException(
            SidecarErrorKind.conflict,
            _detailMessage(error.response?.data) ??
                'sidecar reported a conflict',
            statusCode: status,
            conflictCode: _detailCode(error.response?.data),
            conflictQuestionIds: _detailQuestionIds(error.response?.data),
          );
        }
        return SidecarApiException(
          SidecarErrorKind.badResponse,
          _detailMessage(error.response?.data) ??
              'sidecar returned HTTP $status',
          statusCode: status,
        );
      case DioExceptionType.badCertificate:
      case DioExceptionType.unknown:
        return SidecarApiException(
          SidecarErrorKind.unknown,
          'unexpected sidecar error',
        );
    }
  }
}

/// The value the sidecar knows [role] by -- `annotation_resource`, not the
/// Dart constant's name `annotationResource`.
///
/// `material_roles` is a repeated multipart *form* field, so the generated
/// client types it `BuiltList<String>` and serializes each element as a plain
/// string: the `wireName` mapping [MaterialRole.serializer] carries never gets
/// a chance to run. Passing `role.name` therefore sent enum-constant names the
/// sidecar rejects with 422 `unknown material role`, which left every subject
/// unimportable from the screen while the type checker, the linter and the
/// whole test suite stayed green (Issue #139).
///
/// Goes through the generated serializer rather than a hand-written table:
/// a second copy of the mapping would split again the next time a role is
/// added. [standardSerializers] is the same instance [AutoScoringApi] hands
/// the generated APIs, so this produces exactly what a typed field would.
String _materialRoleWireValue(MaterialRole role) =>
    standardSerializers.serializeWith(MaterialRole.serializer, role)! as String;

/// FastAPI's `{"detail": "..."}` (or our own `{"detail": {"message": "..."}}`
/// shape for structured errors) -- pulls the human-readable text out so
/// callers see *why* a request failed, not just its status code.
String? _detailMessage(Object? data) {
  if (data is! Map) return null;
  final detail = data['detail'];
  if (detail is String) return detail;
  if (detail is Map && detail['message'] is String) {
    return detail['message'] as String;
  }
  return null;
}

/// Our structured errors' `{"detail": {"code": "..."}}` (Issue #150), or
/// `null` if absent/malformed -- see [SidecarApiException.conflictCode].
String? _detailCode(Object? data) {
  if (data is! Map) return null;
  final detail = data['detail'];
  if (detail is! Map) return null;
  final code = detail['code'];
  return code is String ? code : null;
}

/// `POST .../export`'s 409 body's `detail.question_ids` (Issue #23), or
/// `null` if absent/malformed -- see [SidecarApiException.conflictQuestionIds].
List<String>? _detailQuestionIds(Object? data) {
  if (data is! Map) return null;
  final detail = data['detail'];
  if (detail is! Map) return null;
  final ids = detail['question_ids'];
  if (ids is! List) return null;
  return ids.whereType<String>().toList();
}

String _validatedLoopbackBaseUrl(String value) {
  const message = 'sidecar base URL must be an HTTP loopback URL with a port';
  late final Uri uri;
  try {
    uri = Uri.parse(value);
  } on FormatException {
    throw ArgumentError(message);
  }
  if (uri.scheme != 'http' ||
      uri.host != '127.0.0.1' ||
      !uri.hasPort ||
      (uri.path.isNotEmpty && uri.path != '/') ||
      uri.hasQuery ||
      uri.hasFragment ||
      uri.userInfo.isNotEmpty) {
    throw ArgumentError(message);
  }
  return uri.origin;
}
